import axios, { AxiosError, type AxiosResponse } from 'axios'
import { useSnackbar } from 'notistack'
import { useAuthHeader } from 'react-auth-kit'
import { useMutation, useQuery, useQueryClient } from 'react-query'

import { COMMON_MESSAGE } from 'src/data/messages'
import type { ClubId } from 'src/models/club'
import type { MemberLevel } from 'src/models/clubMember'

export interface MemberRequest {
  id: number
  userId: number
  requestedLevel: MemberLevel
  status: 'PENDING' | 'APPROVED' | 'REJECTED'
  name: string
  studentId: string
  phoneNumber: string
  email: string
  department: string
  createdAt: string
  reviewedAt: string | null
  reviewedByUserId: number | null
}

export const useGetMemberRequests = (clubId: ClubId) => {
  const token = useAuthHeader()()
  return useQuery<MemberRequest[]>(['memberRequests', clubId], async () => {
    const response = await axios.get(`${process.env.REACT_APP_APIHOST}/club/${clubId}/member/request`, {
      headers: { Authorization: token }
    })
    return response.data
  })
}

export interface MemberRequestEmailSetting {
  email: string | null
  receiveEmail: boolean
}

export const useGetMemberRequestEmailSetting = (clubId: ClubId) => {
  const token = useAuthHeader()()
  return useQuery<MemberRequestEmailSetting>(['memberRequestEmailSetting', clubId], async () => {
    const response = await axios.get(`${process.env.REACT_APP_APIHOST}/club/${clubId}/member/request/email-setting`, {
      headers: { Authorization: token }
    })
    return response.data
  })
}

export const useUpdateMemberRequestEmailSetting = (clubId: ClubId) => {
  const token = useAuthHeader()()
  const client = useQueryClient()
  const { enqueueSnackbar } = useSnackbar()
  
  return useMutation(
    async (receiveEmail: boolean) => {
      await axios.patch(`${process.env.REACT_APP_APIHOST}/club/${clubId}/member/request/email-setting`, { receiveEmail }, {
        headers: { Authorization: token }
      })
    },
    {
      onSuccess: () => {
        client.invalidateQueries(['memberRequestEmailSetting', clubId])
      },
      onError: () => {
        enqueueSnackbar(COMMON_MESSAGE.SERVER_ERROR, { variant: 'error' })
      }
    }
  )
}

export interface ReviewMemberRequestReqDto {
  userIds: number[]
  accept: boolean
}

export const useReviewMemberRequests = (clubId: ClubId) => {
  const token = useAuthHeader()()
  const client = useQueryClient()
  const { enqueueSnackbar } = useSnackbar()
  
  return useMutation(
    async (reviews: ReviewMemberRequestReqDto) => {
      await axios.patch(`${process.env.REACT_APP_APIHOST}/club/${clubId}/member/request`, reviews, {
        headers: { Authorization: token }
      })
    },
    {
      onSuccess: () => {
        enqueueSnackbar(COMMON_MESSAGE.SUCCESS, { variant: 'success' })
        client.invalidateQueries(['memberRequests', clubId])
        client.invalidateQueries('members')
      },
      onError: () => {
        enqueueSnackbar(COMMON_MESSAGE.SERVER_ERROR, { variant: 'error' })
      }
    }
  )
}

export interface ClubMemberRequestBody {
  memberLevel: MemberLevel
}

interface ClubMemberRequestParams {
  clubId: ClubId
  data: ClubMemberRequestBody
}

const postClubMemberRequest = async ({ clubId, data }: ClubMemberRequestParams, token: string) => {
  await axios.post<null, AxiosResponse<null>, ClubMemberRequestBody>(
    `${process.env.REACT_APP_APIHOST}/club/${clubId}/member/request`,
    data,
    {
      headers: { Authorization: token }
    }
  )
}

export const useRequestClubMember = () => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()

  const mutationFn = (values: ClubMemberRequestParams) => postClubMemberRequest(values, token)

  return useMutation('postClubMemberRequest', mutationFn, {
    onSuccess: () => {
      enqueueSnackbar('회원 인증 신청이 완료되었습니다. 운영진의 수락 메일을 기다려 주세요.', {
        variant: 'success'
      })
    },
    onError: error => {
      if (error instanceof AxiosError) {
        enqueueSnackbar(error.response?.data?.message ?? COMMON_MESSAGE.ADD_FAIL, { variant: 'error' })
      } else {
        enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
      }
    }
  })
}
